            uint x4 = PackF16(pa2.A, pa2.B), x5 = PackF16(pa2.C, pa2.D), x6 = PackF16(pa3.A, pa3.B), x7 = PackF16(pa3.C, pa3.D);
            int o = 0 * BMS * 10 + sr * 10 + kb * 4;
