        }
    }

    /// <summary>Q6_K rows -> f16 words [N][K / 2], bit-identical to the GEMMs' shared-memory decode. idx over N * (K / 32) * 2.</summary>
    /// <summary>The same with row n written at destination row (n / 8) * dstBlock + dstOff + n % 8 (two weights' rows interleaved in 8-row
    /// blocks: FusedDequantMatMul's gate | up SwiGLU GEMM, whose n-tile pairs then hold g and u of the same columns).</summary>
    public static void DequantQ6KF16Rows(Index1D idx, ArrayView<ushort> Wq, ArrayView<W16> O, int N, int K, int dstBlock, int dstOff)
    {
        int bh = idx & 1, rest = idx >> 1;
        int k32n = K >> 5;
        int n = rest / k32n, k32 = rest - n * k32n;
        int kt = k32 << 5;
        long bRow = (long)n * ((K >> 8) * 105);
        long sbL = bRow + (kt >> 8) * 105; int oL = kt & 255, nL = oL >> 7, qqL = (oL >> 5) & 3;
        long qlL = sbL + 32 * nL + 16 * (qqL & 1) + 8 * bh, qhL = sbL + 64 + 16 * nL + 8 * bh;
        int l0 = Wq[qlL + 0]; int l1 = Wq[qlL + 1]; int l2 = Wq[qlL + 2]; int l3 = Wq[qlL + 3]; int l4 = Wq[qlL + 4]; int l5 = Wq[qlL + 5]; int l6 = Wq[qlL + 6]; int l7 = Wq[qlL + 7];
        int h0 = Wq[qhL + 0]; int h1 = Wq[qhL + 1]; int h2 = Wq[qhL + 2]; int h3 = Wq[qhL + 3]; int h4 = Wq[qhL + 4]; int h5 = Wq[qhL + 5]; int h6 = Wq[qhL + 6]; int h7 = Wq[qhL + 7];
        int scw = Wq[sbL + 96 + 4 * nL + qqL], dw = Wq[sbL + 104];
        int qq = (kt >> 5) & 3, lsh = (qq >> 1) * 4, hsh = 2 * qq;
        int scb = bh == 0 ? (scw & 0xFF) : ((scw >> 8) & 0xFF);
        float ds = FusedDequantMatMul.HalfToFloat(dw & 0xFFFF) * (float)((scb ^ 0x80) - 0x80);
        long o = ((long)((n >> 3) * dstBlock + dstOff + (n & 7)) * (K >> 1) + (kt >> 1) + bh * 8) >> 2;   // 16-byte units: two vector stores
        O.AsAligned16()[o + 0] = new W16 { a = (int)Q6Pair(l0, h0, lsh, hsh, ds), b = (int)Q6Pair(l1, h1, lsh, hsh, ds), c = (int)Q6Pair(l2, h2, lsh, hsh, ds), d = (int)Q6Pair(l3, h3, lsh, hsh, ds) };
        O.AsAligned16()[o + 1] = new W16 { a = (int)Q6Pair(l4, h4, lsh, hsh, ds), b = (int)Q6Pair(l5, h5, lsh, hsh, ds), c = (int)Q6Pair(l6, h6, lsh, hsh, ds), d = (int)Q6Pair(l7, h7, lsh, hsh, ds) };
    }

    /// <summary>Q6_K rows -> f16 words [N][K / 2], bit-identical to the GEMMs' shared-memory decode. idx over N * (K / 32) * 2.</summary>
    /// <summary>The same with row n written at destination row (n / 8) * dstBlock + dstOff + n % 8 (two weights' rows interleaved in 8-row
    /// blocks: FusedDequantMatMul's gate | up SwiGLU GEMM, whose n-tile pairs then hold g and u of the same columns).</summary>
    public static void DequantQ6KF16Sm75Rows(Index1D idx, ArrayView<ushort> Wq, ArrayView<W16> O, int N, int K, int dstBlock, int dstOff)
    {
        int bh = idx & 1, rest = idx >> 1;
