        int h0 = Wq[qhL + 0]; int h1 = Wq[qhL + 1]; int h2 = Wq[qhL + 2]; int h3 = Wq[qhL + 3]; int h4 = Wq[qhL + 4]; int h5 = Wq[qhL + 5]; int h6 = Wq[qhL + 6]; int h7 = Wq[qhL + 7];
        int scw = Wq[sbL + 96 + 4 * nL + qqL], dw = Wq[sbL + 104];
        int qq = (kt >> 5) & 3, lsh = (qq >> 1) * 4, hsh = 2 * qq;
